/// Ports already handed to a server in this process. A port is never used twice, so a request
/// that outlives its test cannot reach the server of a later one.
private final class UsedPorts: @unchecked Sendable {
    static let shared = UsedPorts()
    private let lock = NSLock()
    private var ports: Set<Int> = []

    /// Returns `false` when the port was already taken by an earlier server.
    func claim(_ port: Int) -> Bool {
        lock.lock()
        defer { lock.unlock() }
        return ports.insert(port).inserted
    }
}

/// Writes one byte to a pipe. A free function, because the server has a `write` of its own.
private func wakeUp(_ descriptor: Int32) {
    var byte: UInt8 = 1
    _ = write(descriptor, &byte, 1)
}

